mapper.select:
SELECT t1.record_plan_id,t1.record_plan_name,t1.record_plan_status,t1.start_date,t1.end_date, t1.is_all_day,t1.stream_type,t1.storage_type,t1.storage_day,t1.is_audio, t1.device_code,t1.channel_code,t1.tenant_id,t1.creator, t1.create_time,t1.modifier,t1.update_time,t1.delete_flag FROM vm_channel_video_plan_t t1 WHERE t1.delete_flag = 0 and t1.device_code in (select d.device_code from vm_order_devices d where delete_flag = 0 and d.ord_status in (0, 1, 2) AND d.tenant_id = t1.tenant_id) and t1.record_plan_status = 1
AND t1.device_code= #{deviceCode}
AND t1.channel_code= #{channelCode}
AND t1.is_all_day= #{isAllDay}
ORDER BY create_time desc

SELECT t1.record_plan_id,t1.record_plan_name,t1.record_plan_status,t1.start_date,t1.end_date, t1.is_all_day,t1.stream_type,t1.storage_type,t1.storage_day,t1.is_audio, t1.device_code,t1.channel_code,t1.creator, t1.create_time,t1.modifier,t1.update_time,t1.delete_flag FROM vm_channel_video_plan_merge_t t1 WHERE t1.delete_flag = 0
AND t1.device_code= #{deviceCode}
AND t1.channel_code= #{channelCode}
ORDER BY create_time desc

select distinct a.start_time as "startTime",a.end_time as "endTime"
from vm_plan_time_section_t a
left join vm_channel_video_plan_t b
on a.record_plan_id = b.record_plan_id
where a.delete_flag = 0
and b.delete_flag = 0
and b.device_code = #{deviceCode}
and b.record_plan_status = 1
and b.channel_code = #{channelCode}
and a.day_of_week = #{dayOfWeek}

SELECT t1.id, t1.record_plan_id, t1.record_plan_status,device_code,channel_code
FROM vm_channel_video_plan_t t1
WHERE t1.delete_flag = 0 AND t1.tenant_id = #{tenantId} AND t1.industry_code =#{industryCode}

    AND t1.record_plan_id in

        #{labelIdItem}


ORDER BY t1.create_time DESC

SELECT cvp.record_plan_id, CASE WHEN DATE_FORMAT(NOW(), '%Y-%m-%d') > cvp.end_date THEN DATE_SUB(cvp.end_date, INTERVAL cvp.storage_day-1 DAY) WHEN DATE_SUB(DATE_FORMAT(NOW(), '%Y-%m-%d'), INTERVAL cvp.storage_day-1 DAY) <= cvp.start_date THEN cvp.start_date ELSE DATE_SUB(DATE_FORMAT(NOW(), '%Y-%m-%d'), INTERVAL cvp.storage_day-1 DAY) END AS start_date, CASE WHEN DATE_FORMAT(NOW(), '%Y-%m-%d') > cvp.end_date THEN cvp.end_date ELSE DATE_FORMAT(NOW(), '%Y-%m-%d') END AS end_date, pts.day_of_week FROM vm_channel_video_plan_t cvp LEFT JOIN vm_plan_time_section_t pts ON cvp.record_plan_id = pts.record_plan_id AND pts.delete_flag = '0' WHERE cvp.delete_flag = '0' AND cvp.app_ver_code = #{appVerCode} AND cvp.industry_code = #{industryCode} AND cvp.tenant_id = #{tenantId} and cvp.device_code in (select d.device_code from vm_order_devices d where delete_flag = '0' AND d.tenant_id = cvp.tenant_id and d.ord_status IN ( 0, 1, 2 )) and (
( cvp.device_code = #{item.deviceCode} AND cvp.channel_code = #{item.channelCode} )
) and ( ( STR_TO_DATE( cvp.start_date, '%Y-%m-%d' ) <= STR_TO_DATE( #{lastDayOfMonth}, '%Y-%m-%d' ) AND STR_TO_DATE( cvp.end_date, '%Y-%m-%d' ) >= STR_TO_DATE( #{firstDayOfMonth}, '%Y-%m-%d' ) )OR(STR_TO_DATE( cvp.start_date, '%Y-%m-%d' ) <= STR_TO_DATE( #{nextLastDayOfMonth}, '%Y-%m-%d' ) AND STR_TO_DATE( cvp.end_date, '%Y-%m-%d' ) >= STR_TO_DATE( #{nextFirstDayOfMonth}, '%Y-%m-%d' )) )
